<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'reports');[$ph,$ids]=rxp_in($ctx['scope_ids']);
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment;filename="reseller-ledger.csv"');$o=fopen('php://output','w');fprintf($o,"\xEF\xBB\xBF");fputcsv($o,['id','from','to','amount','reason','actor','time']);$q=$pdo->prepare("SELECT * FROM reseller_wallet_ledger WHERE actor_reseller_id IN ($ph) ORDER BY id DESC LIMIT 20000");$q->execute($ids);while($r=$q->fetch(PDO::FETCH_ASSOC))fputcsv($o,[$r['id'],$r['from_user_id'],$r['to_user_id'],$r['amount'],$r['reason'],$r['actor_reseller_id'],date('c',(int)$r['created_at'])]);fclose($o);exit;}
try{$q=$pdo->prepare("SELECT * FROM reseller_wallet_ledger WHERE actor_reseller_id IN ($ph) ORDER BY id DESC LIMIT 1000");$q->execute($ids);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM reseller_wallet_ledger WHERE actor_reseller_id IN ($ph) AND from_user_id IN ($ph)");$q->execute(array_merge($ids,$ids));$out=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT status,COUNT(*) c,COALESCE(SUM(price),0) total FROM reseller_service_operations WHERE owner_reseller_id IN ($ph) GROUP BY status");$q->execute($ids);$ops=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$rows=[];$ops=[];$out=0;}
rxp_layout_start($ctx,'گردش مالی','finance.php');?>
<h1 class="rxp-title">گردش مالی نمایندگی</h1><div class="rxp-grid"><div class="rxp-stat"><b><?=rxp_money($out)?></b><span>جمع خروج ثبت‌شده در Ledger</span></div><div class="rxp-stat"><b><?=count($rows)?></b><span>رکورد نمایش‌داده‌شده</span></div><div class="rxp-stat"><b><?=rxp_money($ctx['user']['Balance']??0)?></b><span>موجودی فعلی شما</span></div></div><a class="rxp-btn green" href="?export=csv">خروجی CSV</a><div class="rxp-card"><h2>وضعیت عملیات سرویس</h2><table class="rxp-table"><tr><th>وضعیت</th><th>تعداد</th><th>مبلغ</th></tr><?php foreach($ops as$r):?><tr><td><?=rxp_h($r['status'])?></td><td><?=$r['c']?></td><td><?=rxp_money($r['total'])?></td></tr><?php endforeach;?></table></div><div class="rxp-card"><h2>Ledger</h2><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>زمان</th><th>از</th><th>به</th><th>مبلغ</th><th>علت</th><th>عامل</th></tr><?php foreach($rows as$r):?><tr><td><?=date('Y/m/d H:i',(int)$r['created_at'])?></td><td><?=rxp_h($r['from_user_id'])?></td><td><?=rxp_h($r['to_user_id'])?></td><td><?=rxp_money($r['amount'])?></td><td><?=rxp_h($r['reason'])?></td><td><?=rxp_h($r['actor_reseller_id'])?></td></tr><?php endforeach;?></table></div></div><?php rxp_layout_end();
